  function fareyOrder12(){const list=[];for(let d=1;d<=12;d++)for(let n=0;n<=d;n++){let a=n,b=d;while(b){const t=b;b=a%b;a=t}if(a===1||(n===0&&d===1))list.push(n/d)}list.sort((a,b)=>a-b);return[...new Set(list)]}
